-- NovaWallet — Cloudflare D1 (SQLite) schema
-- Ported 2026-11-20 from supabase/migrations/0001_schema.sql + 0003_levels.sql.
-- Architecture: Firebase Auth owns identity (users.id = Firebase UID, TEXT);
-- all data lives here; access control is enforced by the Worker API
-- (0002_rls.sql Postgres policies do not port — the Worker is the gatekeeper).
--
-- Porting rules:
--   uuid            -> TEXT (IDs generated by the app/Worker)
--   timestamptz     -> TEXT, ISO-8601 UTC, DEFAULT (datetime('now'))
--   numeric(p,s)    -> NUMERIC
--   boolean         -> INTEGER 0/1
--   jsonb           -> TEXT (JSON string)
--   inet            -> TEXT
--   Postgres enums  -> TEXT + CHECK with the same value lists
--   bigserial       -> INTEGER PRIMARY KEY AUTOINCREMENT
--   transfer_funds() plpgsql -> implemented in the Worker (D1 batch)
-- Deliberate change vs the Postgres model: tx_category CHECK also allows
-- 'direct_withdraw', 'swap' and 'earn', which the shipped app already uses.
-- D1 enforces foreign keys per connection (PRAGMA foreign_keys = ON).

CREATE TABLE account_levels (
  level INTEGER PRIMARY KEY CHECK (level BETWEEN 1 AND 4),
  name TEXT NOT NULL, tagline TEXT,
  daily_limit NUMERIC NOT NULL, monthly_limit NUMERIC NOT NULL,
  loan_limit NUMERIC NOT NULL, fee_discount_pct NUMERIC NOT NULL DEFAULT 0,
  requirement TEXT
);
INSERT INTO account_levels VALUES
  (1,'Level 1','Start your wallet journey',25000,200000,10000,0,'Default for every new account'),
  (2,'Level 2','For verified everyday users',50000,500000,30000,5,'KYC verified'),
  (3,'Level 3','Higher limits, lower fees',100000,1000000,60000,10,'KYC verified + 20 completed transactions'),
  (4,'Level 4','Maximum limits, priority support',250000,2500000,100000,20,'KYC verified + 50 transactions + admin review');

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT UNIQUE NOT NULL, phone TEXT UNIQUE, username TEXT UNIQUE NOT NULL,
  password_hash TEXT, -- Firebase Auth owns credentials; kept for model parity
  pin_hash TEXT NOT NULL, -- transaction PIN hash only (argon2/bcrypt in the Worker)
  role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','frozen')),
  level INTEGER NOT NULL DEFAULT 1 REFERENCES account_levels(level),
  referral_code TEXT UNIQUE NOT NULL,
  referred_by TEXT REFERENCES users(id),
  two_fa_enabled INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  CONSTRAINT no_self_referral CHECK (referred_by IS NULL OR referred_by <> id)
);
CREATE TABLE user_profiles (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  full_name TEXT NOT NULL, avatar_url TEXT, language TEXT NOT NULL DEFAULT 'en',
  theme TEXT NOT NULL DEFAULT 'dark', notification_prefs TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE user_sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  device TEXT, ip TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE currencies (code TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('fiat','crypto')), decimals INTEGER NOT NULL DEFAULT 2, bdt_rate NUMERIC);
INSERT INTO currencies VALUES
 ('BDT','Bangladeshi Taka','fiat',2,1),('USD','US Dollar','fiat',2,121),
 ('BTC','Bitcoin','crypto',8,NULL),('ETH','Ethereum','crypto',8,NULL),
 ('USDT','Tether','crypto',6,NULL),('BNB','BNB','crypto',8,NULL),
 ('SOL','Solana','crypto',9,NULL),('XRP','XRP','crypto',6,NULL);
CREATE TABLE wallets (
  id TEXT PRIMARY KEY,
  user_id TEXT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE wallet_balances (
  wallet_id TEXT NOT NULL REFERENCES wallets(id) ON DELETE CASCADE,
  currency TEXT NOT NULL REFERENCES currencies(code),
  available NUMERIC NOT NULL DEFAULT 0 CHECK (available >= 0),
  locked NUMERIC NOT NULL DEFAULT 0 CHECK (locked >= 0),
  PRIMARY KEY (wallet_id, currency)
);
-- Immutable double-entry ledger: balances are derived, never edited directly.
CREATE TABLE transaction_ledger (
  id TEXT PRIMARY KEY,
  transaction_id TEXT NOT NULL, account TEXT NOT NULL,
  debit NUMERIC NOT NULL DEFAULT 0 CHECK (debit >= 0),
  credit NUMERIC NOT NULL DEFAULT 0 CHECK (credit >= 0),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  CONSTRAINT debit_xor_credit CHECK ((debit > 0) <> (credit > 0))
);
CREATE TABLE transactions (
  id TEXT PRIMARY KEY,
  public_id TEXT UNIQUE NOT NULL, -- 'TXN-…' generated by the Worker
  user_id TEXT NOT NULL REFERENCES users(id),
  category TEXT NOT NULL CHECK (category IN ('add_money','cash_out','send','receive','referral','loan_disbursement','loan_repayment','crypto_buy','crypto_sell','adjustment','direct_withdraw','swap','earn')),
  title TEXT NOT NULL,
  amount NUMERIC NOT NULL CHECK (amount > 0), fee NUMERIC NOT NULL DEFAULT 0,
  currency TEXT NOT NULL REFERENCES currencies(code),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','approved','rejected','active','repaid')),
  note TEXT, counterparty TEXT REFERENCES users(id), method TEXT,
  idempotency_key TEXT UNIQUE,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX idx_tx_user_time ON transactions(user_id, created_at DESC);
CREATE TABLE payment_methods (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE, -- null = platform-owned receiving method
  kind TEXT NOT NULL, label TEXT NOT NULL, account_ref TEXT NOT NULL, is_default INTEGER DEFAULT 0
);
CREATE TABLE deposits (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id), method TEXT NOT NULL,
  amount NUMERIC NOT NULL CHECK (amount > 0), provider_trx_id TEXT NOT NULL,
  receipt_url TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','approved','rejected','active','repaid')),
  reviewed_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (method, provider_trx_id)
);
CREATE TABLE withdrawals (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id), method TEXT NOT NULL,
  amount NUMERIC NOT NULL CHECK (amount > 0), fee NUMERIC NOT NULL DEFAULT 0,
  destination TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','approved','rejected','active','repaid')),
  reviewed_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE transfers (
  id TEXT PRIMARY KEY,
  transaction_id TEXT NOT NULL REFERENCES transactions(id),
  from_user TEXT NOT NULL REFERENCES users(id), to_user TEXT NOT NULL REFERENCES users(id),
  amount NUMERIC NOT NULL CHECK (amount > 0), fee NUMERIC NOT NULL DEFAULT 0,
  CONSTRAINT no_self_transfer CHECK (from_user <> to_user)
);
CREATE TABLE referrals (
  id TEXT PRIMARY KEY,
  referrer_id TEXT NOT NULL REFERENCES users(id), referred_id TEXT UNIQUE NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE referral_commissions (
  id TEXT PRIMARY KEY,
  referral_id TEXT NOT NULL REFERENCES referrals(id),
  amount NUMERIC NOT NULL, source_transaction TEXT REFERENCES transactions(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE loan_applications (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id), amount NUMERIC NOT NULL,
  months INTEGER NOT NULL CHECK (months BETWEEN 1 AND 36), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','approved','rejected','active','repaid')),
  reviewed_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE loans (
  id TEXT PRIMARY KEY,
  application_id TEXT REFERENCES loan_applications(id),
  user_id TEXT NOT NULL REFERENCES users(id), principal NUMERIC NOT NULL,
  rate_pct NUMERIC NOT NULL, months INTEGER NOT NULL, emi NUMERIC NOT NULL,
  total_payable NUMERIC NOT NULL, paid NUMERIC NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('pending','processing','completed','approved','rejected','active','repaid')), created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE loan_repayments (
  id TEXT PRIMARY KEY,
  loan_id TEXT NOT NULL REFERENCES loans(id), amount NUMERIC NOT NULL CHECK (amount > 0),
  transaction_id TEXT REFERENCES transactions(id), created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE crypto_assets (symbol TEXT PRIMARY KEY, name TEXT NOT NULL, gecko_id TEXT NOT NULL, is_active INTEGER DEFAULT 1);
INSERT INTO crypto_assets VALUES ('BTC','Bitcoin','bitcoin',1),('ETH','Ethereum','ethereum',1),('USDT','Tether','tether',1),('BNB','BNB','binancecoin',1),('SOL','Solana','solana',1),('XRP','XRP','ripple',1);
CREATE TABLE crypto_prices (
  id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL REFERENCES crypto_assets(symbol),
  price_usd NUMERIC NOT NULL, change_24h NUMERIC, market_cap NUMERIC,
  source TEXT NOT NULL DEFAULT 'coingecko', captured_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE watchlists (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  symbol TEXT NOT NULL REFERENCES crypto_assets(symbol), PRIMARY KEY (user_id, symbol)
);
CREATE TABLE news (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL,
  excerpt TEXT NOT NULL, body TEXT NOT NULL, source TEXT NOT NULL, featured INTEGER DEFAULT 0,
  coin TEXT DEFAULT 'NOVA',
  published_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE notifications (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, is_read INTEGER DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE kyc_submissions (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id),
  doc_type TEXT NOT NULL, doc_number TEXT NOT NULL, doc_url TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('unverified','pending','verified')), reviewed_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE support_tickets (
  id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id),
  subject TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE banners (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, subtitle TEXT,
  gradient TEXT, is_active INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 0
);
CREATE TABLE platform_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO platform_settings VALUES
 ('fees','{"send_pct":0.5,"cashout_pct":1.5}'), ('referral','{"commission_pct":5}'),
 ('loan','{"rate_pct":12,"min":1000,"max":100000,"limit":100000}'),
 ('rates','{"bdt_per_usd":121}'), ('maintenance','{"enabled":false}');
CREATE TABLE admin_users (user_id TEXT PRIMARY KEY REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE admin_roles (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL);
INSERT INTO admin_roles (id, name) VALUES
 ('role-super-admin','super_admin'),('role-finance','finance'),('role-content','content'),('role-support','support');
CREATE TABLE admin_permissions (
  role_id TEXT NOT NULL REFERENCES admin_roles(id), permission TEXT NOT NULL,
  PRIMARY KEY (role_id, permission)
);
CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY, actor TEXT REFERENCES users(id),
  action TEXT NOT NULL, detail TEXT, ip TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE level_upgrade_requests (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  from_level INTEGER NOT NULL, to_level INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','approved','rejected','active','repaid')),
  reviewed_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  CONSTRAINT next_level_only CHECK (to_level = from_level + 1)
);
CREATE UNIQUE INDEX one_pending_upgrade_per_user
  ON level_upgrade_requests(user_id) WHERE status = 'pending';
